B=[
('جُحَا وَالْحِمَارُ','Cuhâ ve eşek',[
('كَانَ جُحَا رَجُلًا ظَرِيفًا يَعِيشُ فِي قَرْيَةٍ صَغِيرَةٍ.','Cuhâ küçük bir köyde yaşayan esprili bir adamdı.'),
('وَكَانَ عِنْدَهُ حِمَارٌ يُحِبُّهُ كَثِيرًا.','Çok sevdiği bir eşeği vardı.'),
('فِي يَوْمٍ ذَهَبَ جُحَا وَابْنُهُ إِلَى السُّوقِ مَعَ الْحِمَارِ.','Bir gün Cuhâ ve oğlu eşekle birlikte çarşıya gittiler.'),
('رَكِبَ جُحَا الْحِمَارَ، وَمَشَى ابْنُهُ، فَقَالَ النَّاسُ: «انْظُرُوا! الْأَبُ يَرْكَبُ وَالْوَلَدُ الصَّغِيرُ يَمْشِي!»','Cuhâ eşeğe bindi, oğlu yürüdü; insanlar dedi ki: “Bakın! Baba biniyor, küçük çocuk yürüyor!”'),
('فَنَزَلَ جُحَا، وَرَكِبَ ابْنُهُ، فَقَالَ النَّاسُ: «انْظُرُوا! الْوَلَدُ يَرْكَبُ وَالشَّيْخُ يَمْشِي!»','Cuhâ indi, oğlu bindi; insanlar dedi ki: “Bakın! Çocuk biniyor, yaşlı adam yürüyor!”'),
('فَرَكِبَا مَعًا، فَقَالَ النَّاسُ: «يَا لَهُ مِنْ حِمَارٍ مِسْكِينٍ!»','İkisi birlikte bindi; insanlar dedi ki: “Zavallı eşek!”'),
('فَنَزَلَا وَمَشَيَا، فَقَالَ النَّاسُ: «مَعَهُمَا حِمَارٌ وَيَمْشِيَانِ! مَا أَغْبَاهُمَا!»','İkisi inip yürüdü; insanlar dedi ki: “Yanlarında eşek var ve yürüyorlar! Ne kadar akılsızlar!”'),
('فَقَالَ جُحَا لِابْنِهِ: «يَا بُنَيَّ، رِضَا النَّاسِ غَايَةٌ لَا تُدْرَكُ.»','Cuhâ oğluna dedi ki: “Oğulcuğum, insanların rızası ulaşılamayan bir hedeftir.”')]),
('كُلِي يَا ثِيَابِي','Ye kürküm ye',[
('دُعِيَ جُحَا إِلَى وَلِيمَةٍ، فَذَهَبَ بِثِيَابٍ قَدِيمَةٍ.','Cuhâ bir ziyafete davet edildi ve eski elbiselerle gitti.'),
('فَلَمْ يَنْظُرْ إِلَيْهِ أَحَدٌ، وَلَمْ يُقَدِّمُوا لَهُ طَعَامًا.','Kimse ona bakmadı ve ona yemek ikram etmediler.'),
('فَرَجَعَ إِلَى بَيْتِهِ، وَلَبِسَ ثِيَابًا جَدِيدَةً جَمِيلَةً.','Evine döndü ve yeni, güzel elbiseler giydi.'),
('ثُمَّ رَجَعَ إِلَى الْوَلِيمَةِ، فَقَامَ لَهُ النَّاسُ، وَأَجْلَسُوهُ فِي أَحْسَنِ مَكَانٍ.','Sonra ziyafete döndü; insanlar onun için ayağa kalktılar ve onu en güzel yere oturttular.'),
('وَقَدَّمُوا لَهُ أَطْيَبَ الطَّعَامِ.','Ona en güzel yemekleri ikram ettiler.'),
('فَأَخَذَ جُحَا كُمَّ ثَوْبِهِ، وَوَضَعَهُ فِي الطَّعَامِ، وَقَالَ: «كُلْ يَا كُمِّي، كُلْ!»','Cuhâ elbisesinin yenini tuttu, onu yemeğe koydu ve dedi ki: “Ye yenim, ye!”'),
('فَتَعَجَّبَ النَّاسُ، فَقَالَ: «الْإِكْرَامُ لِلثِّيَابِ، فَلْتَأْكُلِ الثِّيَابُ!»','İnsanlar şaştı; dedi ki: “İkram elbiseyeyse, elbise yesin!”')]),
('الْقِدْرُ الَّتِي وَلَدَتْ','Doğuran tencere',[
('اسْتَعَارَ جُحَا قِدْرًا مِنْ جَارِهِ.','Cuhâ komşusundan bir tencere ödünç aldı.'),
('وَبَعْدَ أَيَّامٍ رَدَّهَا، وَفِيهَا قِدْرٌ صَغِيرَةٌ.','Günler sonra onu geri verdi; içinde küçük bir tencere vardı.'),
('قَالَ الْجَارُ: «مَا هَذِهِ؟» قَالَ جُحَا: «قِدْرُكَ وَلَدَتْ عِنْدِي.»','Komşu dedi ki: “Bu ne?” Cuhâ dedi ki: “Tencerin bende doğurdu.”'),
('فَفَرِحَ الْجَارُ وَأَخَذَ الْقِدْرَيْنِ.','Komşu sevindi ve iki tencereyi aldı.'),
('وَبَعْدَ شَهْرٍ اسْتَعَارَ جُحَا الْقِدْرَ مَرَّةً أُخْرَى، وَلَمْ يَرُدَّهَا.','Bir ay sonra Cuhâ tencereyi yine ödünç aldı ve geri vermedi.'),
('فَجَاءَ الْجَارُ يَسْأَلُ عَنْهَا، فَقَالَ جُحَا: «الْبَقَاءُ لِلَّهِ، قِدْرُكَ مَاتَتْ.»','Komşu onu sormaya geldi; Cuhâ dedi ki: “Başın sağ olsun, tencerin öldü.”'),
('قَالَ الْجَارُ: «وَهَلْ تَمُوتُ الْقِدْرُ؟» قَالَ جُحَا: «صَدَّقْتَ أَنَّهَا تَلِدُ، فَلِمَاذَا لَا تُصَدِّقُ أَنَّهَا تَمُوتُ؟»','Komşu dedi ki: “Tencere ölür mü?” Cuhâ dedi ki: “Doğurduğuna inandın da, öldüğüne neden inanmıyorsun?”')]),
('الْقَمَرُ فِي الْبِئْرِ','Kuyudaki ay',[
('نَظَرَ جُحَا لَيْلَةً فِي بِئْرٍ، فَرَأَى الْقَمَرَ فِي الْمَاءِ.','Cuhâ bir gece bir kuyuya baktı ve ayı suyun içinde gördü.'),
('فَقَالَ: «مِسْكِينٌ! سَقَطَ الْقَمَرُ فِي الْبِئْرِ، يَجِبُ أَنْ أُخْرِجَهُ.»','Dedi ki: “Zavallı! Ay kuyuya düşmüş, onu çıkarmalıyım.”'),
('فَجَاءَ بِحَبْلٍ فِيهِ خُطَّافٌ، وَأَلْقَاهُ فِي الْبِئْرِ.','Ucunda kanca olan bir ip getirdi ve onu kuyuya attı.'),
('فَعَلِقَ الْخُطَّافُ بِحَجَرٍ، فَشَدَّ جُحَا بِقُوَّةٍ.','Kanca bir taşa takıldı; Cuhâ kuvvetle çekti.'),
('فَانْقَطَعَ الْحَبْلُ، وَسَقَطَ جُحَا عَلَى ظَهْرِهِ.','İp koptu ve Cuhâ sırtüstü düştü.'),
('فَنَظَرَ إِلَى السَّمَاءِ، فَرَأَى الْقَمَرَ فِيهَا.','Gökyüzüne baktı ve ayı orada gördü.'),
('فَقَالَ: «الْحَمْدُ لِلَّهِ! تَعِبْتُ كَثِيرًا، وَلَكِنَّ الْقَمَرَ رَجَعَ إِلَى مَكَانِهِ.»','Dedi ki: “Elhamdülillah! Çok yoruldum ama ay yerine döndü.”')]),
('خُطْبَةُ جُحَا','Cuhâ’nın hutbesi',[
('صَعِدَ جُحَا الْمِنْبَرَ يَوْمًا، وَقَالَ: «يَا نَاسُ، هَلْ تَعْرِفُونَ مَاذَا سَأَقُولُ لَكُمْ؟»','Cuhâ bir gün minbere çıktı ve dedi ki: “Ey insanlar, size ne söyleyeceğimi biliyor musunuz?”'),
('قَالُوا: «لَا.» قَالَ: «إِذَا كُنْتُمْ لَا تَعْرِفُونَ، فَلَا فَائِدَةَ مِنَ الْكَلَامِ.» وَنَزَلَ.','Dediler ki: “Hayır.” Dedi ki: “Bilmiyorsanız konuşmanın faydası yok.” Ve indi.'),
('فِي الْأُسْبُوعِ التَّالِي سَأَلَهُمْ نَفْسَ السُّؤَالِ، فَقَالُوا: «نَعَمْ.»','Ertesi hafta onlara aynı soruyu sordu; dediler ki: “Evet.”'),
('قَالَ: «إِذَا كُنْتُمْ تَعْرِفُونَ، فَلَا حَاجَةَ أَنْ أَقُولَ.» وَنَزَلَ.','Dedi ki: “Biliyorsanız söylememe gerek yok.” Ve indi.'),
('فِي الْأُسْبُوعِ الثَّالِثِ قَالَ بَعْضُهُمْ: «نَعَمْ»، وَقَالَ بَعْضُهُمْ: «لَا».','Üçüncü hafta bazıları “evet”, bazıları “hayır” dedi.'),
('فَقَالَ جُحَا: «فَلْيُخْبِرِ الَّذِينَ يَعْرِفُونَ الَّذِينَ لَا يَعْرِفُونَ.»','Cuhâ dedi ki: “O hâlde bilenler bilmeyenlere anlatsın.”'),
('ثُمَّ نَزَلَ، وَضَحِكَ النَّاسُ كَثِيرًا.','Sonra indi; insanlar çok güldü.')]),
('رَائِحَةُ الطَّعَامِ','Yemeğin kokusu',[
('جَلَسَ رَجُلٌ فَقِيرٌ أَمَامَ مَطْعَمٍ، وَأَكَلَ خُبْزَهُ مَعَ رَائِحَةِ الشِّوَاءِ.','Fakir bir adam bir lokantanın önüne oturdu ve ekmeğini kebabın kokusuyla yedi.'),
('فَخَرَجَ صَاحِبُ الْمَطْعَمِ وَقَالَ: «ادْفَعْ ثَمَنَ الرَّائِحَةِ!»','Lokantanın sahibi çıktı ve dedi ki: “Kokunun parasını öde!”'),
('فَذَهَبَا إِلَى جُحَا، وَكَانَ قَاضِيَ الْقَرْيَةِ.','İkisi köyün kadısı olan Cuhâ’ya gittiler.'),
('سَمِعَ جُحَا الْقِصَّةَ، ثُمَّ أَخْرَجَ دَرَاهِمَ مِنْ جَيْبِهِ.','Cuhâ hikâyeyi dinledi, sonra cebinden dirhemler çıkardı.'),
('وَحَرَّكَهَا فِي يَدِهِ أَمَامَ أُذُنِ صَاحِبِ الْمَطْعَمِ، فَسُمِعَ صَوْتُهَا.','Onları lokanta sahibinin kulağının önünde elinde salladı; sesleri duyuldu.'),
('ثُمَّ قَالَ: «هَلْ سَمِعْتَ صَوْتَ الدَّرَاهِمِ؟» قَالَ: «نَعَمْ.»','Sonra dedi ki: “Dirhemlerin sesini duydun mu?” Dedi ki: “Evet.”'),
('قَالَ جُحَا: «إِذَنْ أَخَذْتَ حَقَّكَ: ثَمَنُ الرَّائِحَةِ صَوْتُ الدَّرَاهِمِ.»','Cuhâ dedi ki: “O hâlde hakkını aldın: kokunun bedeli paranın sesidir.”')]),
]
